    [3, 0, 0, 0, 0, 0, 0, 5, 5, 0]
]

from collections import defaultdict

def analyze_components(grid):
    color_info = {}
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp_cells = []
                queue = [(r, c)]

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) not in visited:
                        visited.add((curr_r, curr_c))
                        comp_cells.append((curr_r, curr_c))

                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] == color and (nr, nc) not in visited:
                                    queue.append((nr, nc))

                if color not in color_info:
                    color_info[color] = []
                min_r = min(cell[0] for cell in comp_cells)
                max_r = max(cell[0] for cell in comp_cells)
                height = max_r - min_r + 1
                min_c = min(cell[1] for cell in comp_cells)
                color_info[color].append({
                    'cells': comp_cells,
                    'height': height,
                    'min_c': min_c
                })

    return color_info

color_info = analyze_components(test_input)

print("Component analysis:")
for color in sorted(color_info.keys()):
    print(f"\nColor {color}:")
    for i, comp in enumerate(color_info[color]):
        print(f"  Comp {i}: height={comp['height']}, min_c={comp['min_c']}")

