from collections import defaultdict

def find_components(grid):
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = {'color': color, 'cells': [], 'max_r': float('-inf')}

                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) not in visited:
                        visited.add((curr_r, curr_c))
                        comp['cells'].append((curr_r, curr_c))
                        comp['max_r'] = max(comp['max_r'], curr_r)

                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] == color and (nr, nc) not in visited:
                                    queue.append((nr, nc))

                components.append(comp)

    return components

components = find_components(test_input)

print(f"Found {len(components)} components")
for i, comp in enumerate(components):
    print(f"  Comp {i}: color={comp['color']}, cells={comp['cells']}, max_r={comp['max_r']}")

output = [[0]*10 for _ in range(10)]

# Place each component at row = max_r
for comp in components:
    target_row = comp['max_r']
    for r, c in comp['cells']:
        output[target_row][c] = comp['color']

print("\nOutput after simple placement:")
for row in output:
    print(' '.join(map(str, row)))

